mapper.select:
SELECT ss.*,s.supplier_code,s.supplier_name
  FROM the_full_order.tb_supplier_account_site ss
  JOIN the_full_order.tb_supplier s ON s.supplier_id=ss.supplier_id
 WHERE ss.account_id=#{account_id}
 AND ss.supplier_id=#{supplier_id}
 AND ss.active_yn=#{active_yn}
 ORDER BY s.supplier_name,ss.external_site_name,ss.external_site_code

mapper.update:
UPDATE the_full_order.tb_supplier_site_product_price
   SET effective_to=DATE_SUB(#{effective_from},INTERVAL 1 SECOND)
 WHERE supplier_offer_id=#{supplier_offer_id} AND effective_to IS NULL AND effective_from<#{effective_from}

mapper.select:
SELECT r.*,s.supplier_code,s.supplier_name,COUNT(ri.goods_receipt_item_id) item_count,
       SUM(CASE WHEN ri.reconciliation_status='MISMATCH' THEN 1 ELSE 0 END) mismatch_count
  FROM the_full_order.tb_goods_receipt r JOIN the_full_order.tb_supplier s ON s.supplier_id=r.supplier_id
  LEFT JOIN the_full_order.tb_goods_receipt_item ri ON ri.goods_receipt_id=r.goods_receipt_id
 WHERE r.account_id=#{account_id}
 AND r.receipt_date>=#{from_date}
 AND r.receipt_date<=#{to_date}
 GROUP BY r.goods_receipt_id ORDER BY r.receipt_date DESC,r.created_at DESC

SELECT i.*,s.supplier_code,s.supplier_name FROM the_full_order.tb_supplier_incident i
  JOIN the_full_order.tb_supplier s ON s.supplier_id=i.supplier_id WHERE i.account_id=#{account_id}
 AND i.status=#{status}
 ORDER BY COALESCE(i.occurred_at,i.created_at) DESC

mapper.update:
UPDATE the_full_order.tb_supplier_sync_checkpoint SET cursor_value=NULL,last_succeeded_at=NOW(),last_result_code='SUCCESS',
  last_result_message=#{result_message},consecutive_failures=0
 WHERE supplier_id=#{supplier_id} AND supplier_account_site_id=#{supplier_account_site_id} AND sync_type=#{sync_type}

UPDATE the_full_order.tb_supplier_sync_checkpoint SET cursor_value=#{cursor_value},last_failed_at=NOW(),last_result_code='FAILED',
  last_result_message=#{result_message},consecutive_failures=consecutive_failures+1
 WHERE supplier_id=#{supplier_id} AND supplier_account_site_id=#{supplier_account_site_id} AND sync_type=#{sync_type}

mapper.select:
SELECT * FROM the_full_order.tb_account_inventory_balance
 WHERE account_id=#{account_id} AND account_ingredient_product_id=#{account_ingredient_product_id}
   AND location_id=COALESCE(#{location_id},'L999') FOR UPDATE

mapper.update:
UPDATE the_full_order.tb_account_purchase_order_item
   SET item_status=CASE WHEN received_order_qty+#{received_qty}>=order_qty THEN 'RECEIVED' ELSE 'PARTIAL_RECEIVED' END,
       received_order_qty=received_order_qty+#{received_qty}
 WHERE purchase_order_item_id=#{purchase_order_item_id}

UPDATE the_full_order.tb_account_purchase_order po
   SET po.status=CASE WHEN NOT EXISTS(
     SELECT 1 FROM the_full_order.tb_account_purchase_order_item x
      WHERE x.purchase_order_id=po.purchase_order_id AND x.received_order_qty<x.order_qty
   ) THEN 'RECEIVED' ELSE 'PARTIAL_RECEIVED' END,
   po.received_at=CASE WHEN NOT EXISTS(
     SELECT 1 FROM the_full_order.tb_account_purchase_order_item x
      WHERE x.purchase_order_id=po.purchase_order_id AND x.received_order_qty<x.order_qty
   ) THEN NOW() ELSE po.received_at END
 WHERE po.purchase_order_id=#{purchase_order_id}
